class Solution:
    def numberCount(self, a: int, b: int) -> int:
        return sum(1 for x in range(a, b + 1) if len(str(x)) == len(set(str(x))))

class Solution {
public:
    int numberCount(int a, int b) {
        int ans = 0;
        for (int x = a; x <= b; ++x) {
            int mask = 0, cur = x;
            bool ok = true;
            while (cur > 0) {
                int d = cur % 10;
                if (mask & (1 << d)) { ok = false; break; }
                mask |= (1 << d);
                cur /= 10;
            }
            if (ok) ans++;
        }
        return ans;
    }
};

class Solution {
    public int numberCount(int a, int b) {
        int ans = 0;
        for (int x = a; x <= b; ++x) {
            int mask = 0, cur = x;
            boolean ok = true;
            while (cur > 0) {
                int d = cur % 10;
                if ((mask & (1 << d)) != 0) { ok = false; break; }
                mask |= (1 << d);
                cur /= 10;
            }
            if (ok) ans++;
        }
        return ans;
    }
}

var numberCount = function(a, b) {
    let ans = 0;
    for (let x = a; x <= b; ++x) {
        const s = String(x);
        if (s.length === new Set(s).size) ans++;
    }
    return ans;
};
